mapper.select:
SELECT DISTINCT provider_financial_data_status
FROM report_orders
WHERE store_id = #{storeId}
AND status IN ('DELIVERED', 'REFUNDED')
AND provider_financial_data_status IS NOT NULL
AND ordered_at >= #{from}
AND ordered_at <= #{to}
AND platform_type = #{platformType}
ORDER BY provider_financial_data_status

SELECT rc.provider_cancel_code AS reasonCode, COUNT(DISTINCT ro.order_id) AS count
FROM report_orders ro INNER JOIN report_cancellations rc ON rc.order_id = ro.order_id
WHERE ro.store_id = #{storeId} AND ro.status = 'CANCELED' AND rc.provider_cancel_code IS NOT NULL AND TRIM(rc.provider_cancel_code) != ''
AND ro.ordered_at >= #{from}
AND ro.ordered_at <= #{to}
AND ro.platform_type = #{platformType}
GROUP BY rc.provider_cancel_code ORDER BY count DESC, reasonCode ASC LIMIT 5

SELECT history.order_id AS orderId, history.platform_type AS platformType, history.platform_order_id AS platformOrderId, history.history_type AS historyType, history.reason_code AS reasonCode, history.reason_text AS reasonText, history.amount AS amount, history.refund_status AS refundStatus, history.occurred_at AS occurredAt FROM ( SELECT ro.order_id, ro.platform_type, ro.platform_order_id, 'CANCELED' AS history_type, rc.provider_cancel_code AS reason_code, rc.provider_cancel_reason AS reason_text, NULL AS amount, NULL AS refund_status, rc.canceled_at AS occurred_at FROM report_orders ro INNER JOIN report_cancellations rc ON rc.order_id = ro.order_id WHERE ro.store_id = #{storeId}
AND rc.canceled_at >= #{from}
AND rc.canceled_at <= #{to}
AND ro.platform_type = #{platformType}
UNION ALL
SELECT ro.order_id, ro.platform_type, ro.platform_order_id, CASE WHEN rr.status = 'REFUNDED' THEN 'REFUNDED' ELSE 'REFUND_REQUESTED' END AS history_type, rr.reason_code, rr.reason_text, rr.amount, rr.status AS refund_status, rr.requested_at AS occurred_at FROM report_orders ro INNER JOIN report_refunds rr ON rr.order_id = ro.order_id WHERE ro.store_id = #{storeId}
AND rr.requested_at >= #{from}
AND rr.requested_at <= #{to}
AND ro.platform_type = #{platformType}
) history ORDER BY history.occurred_at DESC, history.order_id DESC

WITH filtered_orders AS ( SELECT ro.order_id, ro.platform_type, ro.status, ro.gross_order_amount
FROM report_orders ro
WHERE ro.store_id = #{storeId}
AND ro.ordered_at >= #{from}
AND ro.ordered_at <= #{to}
AND ro.platform_type = #{platformType}
), completed_items_by_order AS ( SELECT fo.order_id, COALESCE( SUM(ri.ordered_unit_price * ri.quantity), 0 ) AS item_order_amount
FROM filtered_orders fo INNER JOIN report_order_items ri ON ri.order_id = fo.order_id
WHERE fo.status = 'DELIVERED'
GROUP BY fo.order_id ) SELECT fo.platform_type AS platformType, COUNT(*) AS totalOrderCount, COALESCE( SUM(CASE WHEN fo.status = 'DELIVERED' THEN 1 ELSE 0 END), 0 ) AS completedOrderCount, COALESCE( SUM(CASE WHEN fo.status = 'CANCELED' THEN 1 ELSE 0 END), 0 ) AS canceledOrderCount, COALESCE( SUM( CASE WHEN fo.status = 'DELIVERED' THEN COALESCE(fo.gross_order_amount, ci.item_order_amount, 0) ELSE 0 END ), 0 ) AS grossSales
FROM filtered_orders fo LEFT JOIN completed_items_by_order ci ON ci.order_id = fo.order_id
GROUP BY fo.platform_type ORDER BY fo.platform_type ASC

SELECT
    rc.order_id AS orderId,
    rc.charge_type AS chargeType,
    rc.amount AS amount
FROM report_order_charges rc
INNER JOIN report_orders ro ON ro.order_id = rc.order_id
WHERE ro.store_id = #{storeId}
  AND ro.status = 'DELIVERED'
AND ro.ordered_at  >=  #{from}
AND ro.ordered_at  <=  #{to}
AND ro.platform_type = #{platformType}
ORDER BY rc.order_id ASC, rc.charge_type ASC
